local args = { ... }
if not args[1] then
    error("Usage: qrdecode <path/to/image.png|jpg>", 0)
    end
    local path = shell and shell.resolve(args[1]) or args[1]
    local function fastYield()
    os.queueEvent("qr_yield")
    os.pullEvent("qr_yield")
    end
    local gpu = peripheral.find("directgpu")
    if not gpu then error("No directgpu peripheral attached.", 0) end
        if type(gpu.decodeImage) ~= "function" then
            error("This directgpu peripheral does not support decodeImage().", 0)
            end
            if not fs.exists(path) then error("File not found: " .. path, 0) end
                local fh = fs.open(path, "rb")
                if not fh then error("Could not open file: " .. path, 0) end
                    local raw = fh.readAll()
                    fh.close()
                    local base64 = require and require("cc.base64")
                    if not base64 then
                        local ok, mod = pcall(dofile, "/rom/modules/main/cc/base64.lua")
                        if ok then base64 = mod end
                            end
                            if not base64 then error("cc.base64 module not available.", 0) end
                                local b64data = base64.encode(raw)
                                local decoded = gpu.decodeImage(b64data)
                                if not decoded or not decoded.pixels or not decoded.width or not decoded.height then
                                    error("Failed to decode image (unsupported format or corrupt file).", 0)
                                    end
                                    local W, H = decoded.width, decoded.height
                                    local PIX = decoded.pixels
                                    print(("Image loaded: %dx%d px"):format(W, H))
                                    local bitmap = {}
                                    do
                                        local gray = {}
                                        local sum = 0
                                        local n = W * H
                                        local sb = string.byte
                                        local off = 1
                                        for i = 1, n do
                                            local r, g, b = sb(PIX, off, off + 2)
                                            local v = 0.299 * r + 0.587 * g + 0.114 * b
                                            gray[i] = v
                                            sum = sum + v
                                            off = off + 3
                                            if i % 25000 == 0 then fastYield() end
                                                end
                                                local thresh = (sum / n) * 0.7
                                                for i = 1, n do
                                                    bitmap[i] = (gray[i] < thresh) and 1 or 0
                                                    if i % 50000 == 0 then fastYield() end
                                                        end
                                                        end
                                                        local function bmIdx(x, y) return y * W + x + 1 end
                                                        local function checkRatio(c0, c1, c2, c3, c4)
                                                        local total = c0 + c1 + c2 + c3 + c4
                                                        if total < 7 then return false end
                                                            local ms = total / 7.0
                                                            local maxv = ms / 1.5
                                                            return math.abs(ms - c0) < maxv and math.abs(ms - c1) < maxv and
                                                            math.abs(3 * ms - c2) < 3 * maxv and math.abs(ms - c3) < maxv and
                                                            math.abs(ms - c4) < maxv
                                                            end
                                                            local function rowRuns(y)
                                                            local runs = {}
                                                            local base = y * W
                                                            local cur = bitmap[base + 1]
                                                            local start = 0
                                                            local n = 0
                                                            for x = 1, W - 1 do
                                                                local v = bitmap[base + x + 1]
                                                                if v ~= cur then
                                                                    n = n + 1
                                                                    runs[n] = { cur, start, x - start }
                                                                    cur = v
                                                                    start = x
                                                                    end
                                                                    end
                                                                    n = n + 1
                                                                    runs[n] = { cur, start, W - start }
                                                                    return runs, n
                                                                    end
                                                                    local function colRuns(x)
                                                                    local runs = {}
                                                                    local cur = bitmap[bmIdx(x, 0)]
                                                                    local start = 0
                                                                    local n = 0
                                                                    for y = 1, H - 1 do
                                                                        local v = bitmap[bmIdx(x, y)]
                                                                        if v ~= cur then
                                                                            n = n + 1
                                                                            runs[n] = { cur, start, y - start }
                                                                            cur = v
                                                                            start = y
                                                                            end
                                                                            end
                                                                            n = n + 1
                                                                            runs[n] = { cur, start, H - start }
                                                                            return runs, n
                                                                            end
                                                                            local function findRowCandidates()
                                                                            local cands, cn = {}, 0
                                                                            for y = 0, H - 1 do
                                                                                local runs, n = rowRuns(y)
                                                                                for i = 1, n - 4 do
                                                                                    local r0, r1, r2, r3, r4 = runs[i], runs[i + 1], runs[i + 2], runs[i + 3], runs[i + 4]
                                                                                    if r0[1] == 1 and r1[1] == 0 and r2[1] == 1 and r3[1] == 0 and r4[1] == 1 then
                                                                                        if checkRatio(r0[3], r1[3], r2[3], r3[3], r4[3]) then
                                                                                            local total = r0[3] + r1[3] + r2[3] + r3[3] + r4[3]
                                                                                            cn = cn + 1
                                                                                            cands[cn] = { r0[2] + total / 2.0, y, total / 7.0 }
                                                                                            end
                                                                                            end
                                                                                            end
                                                                                            if y % 400 == 0 then fastYield() end
                                                                                                end
                                                                                                return cands, cn
                                                                                                end
                                                                                                local function confirmVertical(cx, cy)
                                                                                                local x = math.floor(cx + 0.5)
                                                                                                if x < 0 or x >= W then return nil end
                                                                                                    local runs, n = colRuns(x)
                                                                                                    local idx = nil
                                                                                                    for i = 1, n do
                                                                                                        local r = runs[i]
                                                                                                        if r[2] <= cy and cy < r[2] + r[3] then idx = i; break end
                                                                                                            end
                                                                                                            if not idx or idx - 2 < 1 or idx + 2 > n then return nil end
                                                                                                                local r0, r1, r2, r3, r4 = runs[idx - 2], runs[idx - 1], runs[idx], runs[idx + 1], runs[idx + 2]
                                                                                                                if not (r0[1] == 1 and r1[1] == 0 and r2[1] == 1 and r3[1] == 0 and r4[1] == 1) then return nil end
                                                                                                                    if not checkRatio(r0[3], r1[3], r2[3], r3[3], r4[3]) then return nil end
                                                                                                                        local total = r0[3] + r1[3] + r2[3] + r3[3] + r4[3]
                                                                                                                        return r0[2] + total / 2.0, total / 7.0
                                                                                                                        end
                                                                                                                        local function clusterPoints(points, np, tol)
                                                                                                                        local clusters, cn = {}, 0
                                                                                                                        for i = 1, np do
                                                                                                                            local p = points[i]
                                                                                                                            local placed = false
                                                                                                                            for c = 1, cn do
                                                                                                                                local cl = clusters[c]
                                                                                                                                local last = cl[#cl]
                                                                                                                                if math.abs(last[1] - p[1]) < tol and math.abs(last[2] - p[2]) < tol then
                                                                                                                                    cl[#cl + 1] = p
                                                                                                                                    placed = true
                                                                                                                                    break
                                                                                                                                    end
                                                                                                                                    end
                                                                                                                                    if not placed then
                                                                                                                                        cn = cn + 1
                                                                                                                                        clusters[cn] = { p }
                                                                                                                                        end
                                                                                                                                        end
                                                                                                                                        local out = {}
                                                                                                                                        for c = 1, cn do
                                                                                                                                            local cl = clusters[c]
                                                                                                                                            local n = #cl
                                                                                                                                            local sx, sy, sm = 0, 0, 0
                                                                                                                                            for i = 1, n do sx = sx + cl[i][1]; sy = sy + cl[i][2]; sm = sm + cl[i][3] end
                                                                                                                                                out[c] = { sx / n, sy / n, sm / n, n }
                                                                                                                                                end
                                                                                                                                                return out
                                                                                                                                                end
                                                                                                                                                local function findFinderPatterns()
                                                                                                                                                local rowCands, rn = findRowCandidates()
                                                                                                                                                local confirmed, cn = {}, 0
                                                                                                                                                for i = 1, rn do
                                                                                                                                                    local cx, cy, ms = rowCands[i][1], rowCands[i][2], rowCands[i][3]
                                                                                                                                                    local cyy, vms = confirmVertical(cx, cy)
                                                                                                                                                    if cyy then
                                                                                                                                                        cn = cn + 1
                                                                                                                                                        confirmed[cn] = { cx, cyy, (ms + vms) / 2.0 }
                                                                                                                                                        end
                                                                                                                                                        end
                                                                                                                                                        local clusters = clusterPoints(confirmed, cn, 6)
                                                                                                                                                        table.sort(clusters, function(a, b) return a[4] > b[4] end)
                                                                                                                                                        if #clusters < 3 then
                                                                                                                                                            error("Could not locate 3 QR finder patterns in image (" .. #clusters .. " found).", 0)
                                                                                                                                                            end
                                                                                                                                                            return { clusters[1], clusters[2], clusters[3] }
                                                                                                                                                            end
                                                                                                                                                            local function orderFinderPatterns(pts)
                                                                                                                                                            local function d2(a, b) return (a[1] - b[1]) ^ 2 + (a[2] - b[2]) ^ 2 end
                                                                                                                                                            local d01, d02, d12 = d2(pts[1], pts[2]), d2(pts[1], pts[3]), d2(pts[2], pts[3])
                                                                                                                                                            local topLeft, a, b
                                                                                                                                                            if d01 >= d02 and d01 >= d12 then
                                                                                                                                                                topLeft, a, b = pts[3], pts[1], pts[2]
                                                                                                                                                                elseif d02 >= d01 and d02 >= d12 then
                                                                                                                                                                    topLeft, a, b = pts[2], pts[1], pts[3]
                                                                                                                                                                    else
                                                                                                                                                                        topLeft, a, b = pts[1], pts[2], pts[3]
                                                                                                                                                                        end
                                                                                                                                                                        local topRight, bottomLeft
                                                                                                                                                                        if math.abs(a[2] - topLeft[2]) < math.abs(b[2] - topLeft[2]) then
                                                                                                                                                                            topRight, bottomLeft = a, b
                                                                                                                                                                            else
                                                                                                                                                                                topRight, bottomLeft = b, a
                                                                                                                                                                                end
                                                                                                                                                                                return topLeft, topRight, bottomLeft
                                                                                                                                                                                end
                                                                                                                                                                                local VALID_DIMS = {}
                                                                                                                                                                                do
                                                                                                                                                                                    local i = 1
                                                                                                                                                                                    for d = 21, 177, 4 do VALID_DIMS[i] = d; i = i + 1 end
                                                                                                                                                                                        end
                                                                                                                                                                                        local function nearestValidDim(d)
                                                                                                                                                                                        local best, bestDiff = VALID_DIMS[1], math.huge
                                                                                                                                                                                        for i = 1, #VALID_DIMS do
                                                                                                                                                                                            local diff = math.abs(VALID_DIMS[i] - d)
                                                                                                                                                                                            if diff < bestDiff then bestDiff = diff; best = VALID_DIMS[i] end
                                                                                                                                                                                                end
                                                                                                                                                                                                return best
                                                                                                                                                                                                end
                                                                                                                                                                                                local function buildBitMatrix(topLeft, topRight, bottomLeft)
                                                                                                                                                                                                local rawms = (topLeft[3] + topRight[3] + bottomLeft[3]) / 3.0
                                                                                                                                                                                                local distTR = math.sqrt((topRight[1] - topLeft[1]) ^ 2 + (topRight[2] - topLeft[2]) ^ 2)
                                                                                                                                                                                                local distBL = math.sqrt((bottomLeft[1] - topLeft[1]) ^ 2 + (bottomLeft[2] - topLeft[2]) ^ 2)
                                                                                                                                                                                                local dimGuess = (distTR / rawms + distBL / rawms) / 2.0 + 7
                                                                                                                                                                                                local dimension = nearestValidDim(dimGuess)
                                                                                                                                                                                                local msx = distTR / (dimension - 7)
                                                                                                                                                                                                local msy = distBL / (dimension - 7)
                                                                                                                                                                                                local ux, uy = (topRight[1] - topLeft[1]) / distTR, (topRight[2] - topLeft[2]) / distTR
                                                                                                                                                                                                local vx, vy = (bottomLeft[1] - topLeft[1]) / distBL, (bottomLeft[2] - topLeft[2]) / distBL
                                                                                                                                                                                                local originX = topLeft[1] - ux * 3.5 * msx - vx * 3.5 * msy
                                                                                                                                                                                                local originY = topLeft[2] - uy * 3.5 * msx - vy * 3.5 * msy
                                                                                                                                                                                                local matrix = {}
                                                                                                                                                                                                local function mIdx(row, col) return row * dimension + col + 1 end
                                                                                                                                                                                                for row = 0, dimension - 1 do
                                                                                                                                                                                                    for col = 0, dimension - 1 do
                                                                                                                                                                                                        local px = originX + ux * (col + 0.5) * msx + vx * (row + 0.5) * msy
                                                                                                                                                                                                        local py = originY + uy * (col + 0.5) * msx + vy * (row + 0.5) * msy
                                                                                                                                                                                                        local ix = math.floor(px + 0.5)
                                                                                                                                                                                                        local iy = math.floor(py + 0.5)
                                                                                                                                                                                                        if ix < 0 then ix = 0 elseif ix >= W then ix = W - 1 end
                                                                                                                                                                                                            if iy < 0 then iy = 0 elseif iy >= H then iy = H - 1 end
                                                                                                                                                                                                                matrix[mIdx(row, col)] = bitmap[bmIdx(ix, iy)]
                                                                                                                                                                                                                end
                                                                                                                                                                                                                if row % 40 == 0 then fastYield() end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    return matrix, dimension, mIdx
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local FORMAT_COORDS = {
                                                                                                                                                                                                                        { 8, 0 }, { 8, 1 }, { 8, 2 }, { 8, 3 }, { 8, 4 }, { 8, 5 }, { 8, 7 }, { 8, 8 },
                                                                                                                                                                                                                        { 7, 8 }, { 5, 8 }, { 4, 8 }, { 3, 8 }, { 2, 8 }, { 1, 8 }, { 0, 8 },
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                    local function bchFormatEncode(data5)
                                                                                                                                                                                                                    local g = 0x537
                                                                                                                                                                                                                    local val = bit32.lshift(data5, 10)
                                                                                                                                                                                                                    local tmp = val
                                                                                                                                                                                                                    for i = 4, 0, -1 do
                                                                                                                                                                                                                        if bit32.band(tmp, bit32.lshift(1, i + 10)) ~= 0 then
                                                                                                                                                                                                                            tmp = bit32.bxor(tmp, bit32.lshift(g, i))
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            return bit32.bxor(bit32.bor(val, tmp), 0x5412)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            local ALL_FORMATS = {}
                                                                                                                                                                                                                            for ecc = 0, 3 do
                                                                                                                                                                                                                                for mask = 0, 7 do
                                                                                                                                                                                                                                    local data = bit32.bor(bit32.lshift(ecc, 3), mask)
                                                                                                                                                                                                                                    ALL_FORMATS[bchFormatEncode(data)] = { ecc, mask }
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                    local ECC_BITS_MAP = { [1] = "L", [0] = "M", [3] = "Q", [2] = "H" }
                                                                                                                                                                                                                                    local function popcount15(x)
                                                                                                                                                                                                                                    local c = 0
                                                                                                                                                                                                                                    for i = 0, 14 do
                                                                                                                                                                                                                                        if bit32.band(x, bit32.lshift(1, i)) ~= 0 then c = c + 1 end
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                            return c
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                            local function readFormatInfo(matrix, mIdx)
                                                                                                                                                                                                                                            local bits = 0
                                                                                                                                                                                                                                            for i = 1, #FORMAT_COORDS do
                                                                                                                                                                                                                                                local rc = FORMAT_COORDS[i]
                                                                                                                                                                                                                                                bits = bit32.bor(bit32.lshift(bits, 1), matrix[mIdx(rc[1], rc[2])])
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                local bestEcc, bestMask, bestDist = nil, nil, 99
                                                                                                                                                                                                                                                for code, em in pairs(ALL_FORMATS) do
                                                                                                                                                                                                                                                    local d = popcount15(bit32.bxor(code, bits))
                                                                                                                                                                                                                                                    if d < bestDist then bestDist = d; bestEcc = em[1]; bestMask = em[2] end
                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                        return bestEcc, bestMask
                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                        local function isFunctionModule(row, col, dimension)
                                                                                                                                                                                                                                                        if row < 9 and col < 9 then return true end
                                                                                                                                                                                                                                                            if row < 9 and col >= dimension - 8 then return true end
                                                                                                                                                                                                                                                                if row >= dimension - 8 and col < 9 then return true end
                                                                                                                                                                                                                                                                if row == 6 or col == 6 then return true end
                                                                                                                                                                                                                                                                if row == dimension - 8 and col == 8 then return true end
                                                                                                                                                                                                                                                                return false
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local ALIGN_TABLE = {
                                                                                                                                                                                                                                                                [2] = { 6, 18 }, [3] = { 6, 22 }, [4] = { 6, 26 }, [5] = { 6, 30 }, [6] = { 6, 34 },
                                                                                                                                                                                                                                                                [7] = { 6, 22, 38 }, [8] = { 6, 24, 42 }, [9] = { 6, 26, 46 }, [10] = { 6, 28, 50 },
                                                                                                                                                                                                                                                                [11] = { 6, 30, 54 }, [12] = { 6, 32, 58 }, [13] = { 6, 34, 62 },
                                                                                                                                                                                                                                                                [14] = { 6, 26, 46, 66 }, [15] = { 6, 26, 48, 70 }, [16] = { 6, 26, 50, 74 },
                                                                                                                                                                                                                                                                [17] = { 6, 30, 54, 78 }, [18] = { 6, 30, 56, 82 }, [19] = { 6, 30, 58, 86 },
                                                                                                                                                                                                                                                                [20] = { 6, 34, 62, 90 }, [21] = { 6, 28, 50, 72, 94 }, [22] = { 6, 26, 50, 74, 98 },
                                                                                                                                                                                                                                                                [23] = { 6, 30, 54, 78, 102 }, [24] = { 6, 28, 54, 80, 106 }, [25] = { 6, 32, 58, 84, 110 },
                                                                                                                                                                                                                                                                [26] = { 6, 30, 58, 86, 114 }, [27] = { 6, 34, 62, 90, 118 }, [28] = { 6, 26, 50, 74, 98, 122 },
                                                                                                                                                                                                                                                                [29] = { 6, 30, 54, 78, 102, 126 }, [30] = { 6, 26, 52, 78, 104, 130 },
                                                                                                                                                                                                                                                                [31] = { 6, 30, 56, 82, 108, 134 }, [32] = { 6, 34, 60, 86, 112, 138 },
                                                                                                                                                                                                                                                                [33] = { 6, 30, 58, 86, 114, 142 }, [34] = { 6, 34, 62, 90, 118, 146 },
                                                                                                                                                                                                                                                                [35] = { 6, 30, 54, 78, 102, 126, 150 }, [36] = { 6, 24, 50, 76, 102, 128, 154 },
                                                                                                                                                                                                                                                                [37] = { 6, 28, 54, 80, 106, 132, 158 }, [38] = { 6, 32, 58, 84, 110, 136, 162 },
                                                                                                                                                                                                                                                                [39] = { 6, 26, 54, 82, 110, 138, 166 }, [40] = { 6, 30, 58, 86, 114, 142, 170 },
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                local function buildFuncGrid(dimension, version, mIdx)
                                                                                                                                                                                                                                                                local g = {}
                                                                                                                                                                                                                                                                for row = 0, dimension - 1 do
                                                                                                                                                                                                                                                                for col = 0, dimension - 1 do
                                                                                                                                                                                                                                                                g[mIdx(row, col)] = isFunctionModule(row, col, dimension)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local centers = ALIGN_TABLE[version]
                                                                                                                                                                                                                                                                if centers then
                                                                                                                                                                                                                                                                for _, cr in ipairs(centers) do
                                                                                                                                                                                                                                                                for _, cc in ipairs(centers) do
                                                                                                                                                                                                                                                                local skip = (cr <= 8 and cc <= 8) or (cr <= 8 and cc >= dimension - 9) or
                                                                                                                                                                                                                                                                (cr >= dimension - 9 and cc <= 8)
                                                                                                                                                                                                                                                                if not skip then
                                                                                                                                                                                                                                                                for dr = -2, 2 do
                                                                                                                                                                                                                                                                for dc = -2, 2 do
                                                                                                                                                                                                                                                                g[mIdx(cr + dr, cc + dc)] = true
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if version >= 7 then
                                                                                                                                                                                                                                                                for r = 0, 5 do
                                                                                                                                                                                                                                                                for c = dimension - 11, dimension - 9 do
                                                                                                                                                                                                                                                                g[mIdx(r, c)] = true
                                                                                                                                                                                                                                                                g[mIdx(c, r)] = true
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return g
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local MASK_FUNCS = {
                                                                                                                                                                                                                                                                function(r, c) return (r + c) % 2 == 0 end,
                                                                                                                                                                                                                                                                function(r, c) return r % 2 == 0 end,
                                                                                                                                                                                                                                                                function(r, c) return c % 3 == 0 end,
                                                                                                                                                                                                                                                                function(r, c) return (r + c) % 3 == 0 end,
                                                                                                                                                                                                                                                                function(r, c) return (math.floor(r / 2) + math.floor(c / 3)) % 2 == 0 end,
                                                                                                                                                                                                                                                                function(r, c) return (r * c) % 2 + (r * c) % 3 == 0 end,
                                                                                                                                                                                                                                                                function(r, c) return ((r * c) % 2 + (r * c) % 3) % 2 == 0 end,
                                                                                                                                                                                                                                                                function(r, c) return ((r + c) % 2 + (r * c) % 3) % 2 == 0 end,
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                local function unmaskMatrix(matrix, dimension, maskId, funcGrid, mIdx)
                                                                                                                                                                                                                                                                local mf = MASK_FUNCS[maskId + 1]
                                                                                                                                                                                                                                                                local out = {}
                                                                                                                                                                                                                                                                for row = 0, dimension - 1 do
                                                                                                                                                                                                                                                                for col = 0, dimension - 1 do
                                                                                                                                                                                                                                                                local i = mIdx(row, col)
                                                                                                                                                                                                                                                                local v = matrix[i]
                                                                                                                                                                                                                                                                if not funcGrid[i] and mf(row, col) then v = 1 - v end
                                                                                                                                                                                                                                                                out[i] = v
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return out
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function readCodewords(matrix, dimension, funcGrid, mIdx)
                                                                                                                                                                                                                                                                local bits, bn = {}, 0
                                                                                                                                                                                                                                                                local col = dimension - 1
                                                                                                                                                                                                                                                                local upward = true
                                                                                                                                                                                                                                                                while col > 0 do
                                                                                                                                                                                                                                                                if col == 6 then
                                                                                                                                                                                                                                                                col = col - 1
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                for i = 0, dimension - 1 do
                                                                                                                                                                                                                                                                local row = upward and (dimension - 1 - i) or i
                                                                                                                                                                                                                                                                for _, c in ipairs({ col, col - 1 }) do
                                                                                                                                                                                                                                                                local idx = mIdx(row, c)
                                                                                                                                                                                                                                                                if not funcGrid[idx] then
                                                                                                                                                                                                                                                                bn = bn + 1
                                                                                                                                                                                                                                                                bits[bn] = matrix[idx]
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                upward = not upward
                                                                                                                                                                                                                                                                col = col - 2
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local codewords, cn = {}, 0
                                                                                                                                                                                                                                                                local i = 1
                                                                                                                                                                                                                                                                while i + 7 <= bn do
                                                                                                                                                                                                                                                                local b = 0
                                                                                                                                                                                                                                                                for j = 0, 7 do
                                                                                                                                                                                                                                                                b = bit32.bor(bit32.lshift(b, 1), bits[i + j])
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                cn = cn + 1
                                                                                                                                                                                                                                                                codewords[cn] = b
                                                                                                                                                                                                                                                                i = i + 8
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return codewords, cn
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local GF_EXP, GF_LOG = {}, {}
                                                                                                                                                                                                                                                                do
                                                                                                                                                                                                                                                                local x = 1
                                                                                                                                                                                                                                                                for i = 0, 254 do
                                                                                                                                                                                                                                                                GF_EXP[i] = x
                                                                                                                                                                                                                                                                GF_LOG[x] = i
                                                                                                                                                                                                                                                                x = bit32.lshift(x, 1)
                                                                                                                                                                                                                                                                if bit32.band(x, 0x100) ~= 0 then x = bit32.bxor(x, 0x11D) end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                for i = 255, 511 do GF_EXP[i] = GF_EXP[i - 255] end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function gfMul(a, b)
                                                                                                                                                                                                                                                                if a == 0 or b == 0 then return 0 end
                                                                                                                                                                                                                                                                return GF_EXP[GF_LOG[a] + GF_LOG[b]]
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function gfDiv(a, b)
                                                                                                                                                                                                                                                                if a == 0 then return 0 end
                                                                                                                                                                                                                                                                return GF_EXP[(GF_LOG[a] - GF_LOG[b]) % 255]
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function polyScale(p, k)
                                                                                                                                                                                                                                                                local r = {}
                                                                                                                                                                                                                                                                for i = 1, #p do r[i] = gfMul(p[i], k) end
                                                                                                                                                                                                                                                                return r
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function polyAdd(p, q)
                                                                                                                                                                                                                                                                local n = math.max(#p, #q)
                                                                                                                                                                                                                                                                local r = {}
                                                                                                                                                                                                                                                                for i = 1, n do r[i] = 0 end
                                                                                                                                                                                                                                                                for i = 1, #p do r[i + n - #p] = bit32.bxor(r[i + n - #p], p[i]) end
                                                                                                                                                                                                                                                                for i = 1, #q do r[i + n - #q] = bit32.bxor(r[i + n - #q], q[i]) end
                                                                                                                                                                                                                                                                return r
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function polyMul(p, q)
                                                                                                                                                                                                                                                                local r = {}
                                                                                                                                                                                                                                                                for i = 1, #p + #q - 1 do r[i] = 0 end
                                                                                                                                                                                                                                                                for i = 1, #p do
                                                                                                                                                                                                                                                                local pi = p[i]
                                                                                                                                                                                                                                                                if pi ~= 0 then
                                                                                                                                                                                                                                                                local li = GF_LOG[pi]
                                                                                                                                                                                                                                                                for j = 1, #q do
                                                                                                                                                                                                                                                                local qj = q[j]
                                                                                                                                                                                                                                                                if qj ~= 0 then
                                                                                                                                                                                                                                                                r[i + j - 1] = bit32.bxor(r[i + j - 1], GF_EXP[li + GF_LOG[qj]])
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return r
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function polyEval(p, x)
                                                                                                                                                                                                                                                                local y = p[1]
                                                                                                                                                                                                                                                                for i = 2, #p do y = bit32.bxor(gfMul(y, x), p[i]) end
                                                                                                                                                                                                                                                                return y
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function reversed(t)
                                                                                                                                                                                                                                                                local n = #t
                                                                                                                                                                                                                                                                local r = {}
                                                                                                                                                                                                                                                                for i = 1, n do r[i] = t[n - i + 1] end
                                                                                                                                                                                                                                                                return r
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function rsCalcSyndromes(msg, nsym)
                                                                                                                                                                                                                                                                local s = {}
                                                                                                                                                                                                                                                                for i = 0, nsym - 1 do s[i + 1] = polyEval(msg, GF_EXP[i]) end
                                                                                                                                                                                                                                                                return s
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function rsFindErrorLocator(synd, nsym)
                                                                                                                                                                                                                                                                local errLoc = { 1 }
                                                                                                                                                                                                                                                                local oldLoc = { 1 }
                                                                                                                                                                                                                                                                for i = 0, nsym - 1 do
                                                                                                                                                                                                                                                                oldLoc[#oldLoc + 1] = 0
                                                                                                                                                                                                                                                                local delta = synd[i + 1]
                                                                                                                                                                                                                                                                for j = 1, #errLoc - 1 do
                                                                                                                                                                                                                                                                delta = bit32.bxor(delta, gfMul(errLoc[#errLoc - j], synd[i - j + 1]))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if delta ~= 0 then
                                                                                                                                                                                                                                                                if #oldLoc > #errLoc then
                                                                                                                                                                                                                                                                local newLoc = polyScale(oldLoc, delta)
                                                                                                                                                                                                                                                                oldLoc = polyScale(errLoc, gfDiv(1, delta))
                                                                                                                                                                                                                                                                errLoc = newLoc
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                errLoc = polyAdd(errLoc, polyScale(oldLoc, delta))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                while #errLoc > 0 and errLoc[1] == 0 do table.remove(errLoc, 1) end
                                                                                                                                                                                                                                                                local errs = #errLoc - 1
                                                                                                                                                                                                                                                                if errs * 2 > nsym then return nil end
                                                                                                                                                                                                                                                                return errLoc
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function rsFindErrors(errLoc, nmess)
                                                                                                                                                                                                                                                                local errs = #errLoc - 1
                                                                                                                                                                                                                                                                local errPos, n = {}, 0
                                                                                                                                                                                                                                                                for i = 0, nmess - 1 do
                                                                                                                                                                                                                                                                if polyEval(errLoc, GF_EXP[255 - i]) == 0 then
                                                                                                                                                                                                                                                                n = n + 1
                                                                                                                                                                                                                                                                errPos[n] = nmess - 1 - i
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if n ~= errs then return nil end
                                                                                                                                                                                                                                                                return errPos
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function polyDivmod(dividend, divisor)
                                                                                                                                                                                                                                                                local out = {}
                                                                                                                                                                                                                                                                for i = 1, #dividend do out[i] = dividend[i] end
                                                                                                                                                                                                                                                                for i = 1, #dividend - #divisor + 1 do
                                                                                                                                                                                                                                                                local coef = out[i]
                                                                                                                                                                                                                                                                if coef ~= 0 then
                                                                                                                                                                                                                                                                for j = 2, #divisor do
                                                                                                                                                                                                                                                                if divisor[j] ~= 0 then
                                                                                                                                                                                                                                                                out[i + j - 1] = bit32.bxor(out[i + j - 1], gfMul(divisor[j], coef))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local sep = #dividend - #divisor + 1
                                                                                                                                                                                                                                                                local q, r = {}, {}
                                                                                                                                                                                                                                                                for i = 1, sep do q[i] = out[i] end
                                                                                                                                                                                                                                                                for i = 1, #out - sep do r[i] = out[sep + i] end
                                                                                                                                                                                                                                                                return q, r
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function rsFindErrorEvaluator(synd, errLoc, nsym)
                                                                                                                                                                                                                                                                local p = polyMul(synd, errLoc)
                                                                                                                                                                                                                                                                local divisor = { 1 }
                                                                                                                                                                                                                                                                for i = 1, nsym + 1 do divisor[i + 1] = 0 end
                                                                                                                                                                                                                                                                local _, remainder = polyDivmod(p, divisor)
                                                                                                                                                                                                                                                                return remainder
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function rsCorrectErrata(msg, synd, errPos)
                                                                                                                                                                                                                                                                local n = #errPos
                                                                                                                                                                                                                                                                local coefPos = {}
                                                                                                                                                                                                                                                                for i = 1, n do coefPos[i] = #msg - errPos[i] end
                                                                                                                                                                                                                                                                local errLoc = { 1 }
                                                                                                                                                                                                                                                                for i = 1, n do errLoc = polyMul(errLoc, { GF_EXP[coefPos[i]], 1 }) end
                                                                                                                                                                                                                                                                local syndRev = reversed(synd)
                                                                                                                                                                                                                                                                local errEvalRev = rsFindErrorEvaluator(syndRev, errLoc, #errLoc - 1)
                                                                                                                                                                                                                                                                local errEval = reversed(errEvalRev)
                                                                                                                                                                                                                                                                local X = {}
                                                                                                                                                                                                                                                                for i = 1, n do X[i] = GF_EXP[255 - coefPos[i]] end
                                                                                                                                                                                                                                                                local E = {}
                                                                                                                                                                                                                                                                for i = 1, #msg do E[i] = 0 end
                                                                                                                                                                                                                                                                for i = 1, n do
                                                                                                                                                                                                                                                                local Xi = X[i]
                                                                                                                                                                                                                                                                local XiInv = gfDiv(1, Xi)
                                                                                                                                                                                                                                                                local errlocPrime = 1
                                                                                                                                                                                                                                                                for j = 1, n do
                                                                                                                                                                                                                                                                if j ~= i then
                                                                                                                                                                                                                                                                errlocPrime = gfMul(errlocPrime, bit32.bxor(1, gfMul(XiInv, X[j])))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if errlocPrime ~= 0 then
                                                                                                                                                                                                                                                                local y = polyEval(reversed(errEval), XiInv)
                                                                                                                                                                                                                                                                y = gfMul(Xi, y)
                                                                                                                                                                                                                                                                E[errPos[i] + 1] = gfDiv(y, errlocPrime)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local out = {}
                                                                                                                                                                                                                                                                for i = 1, #msg do out[i] = bit32.bxor(msg[i], E[i]) end
                                                                                                                                                                                                                                                                return out
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function rsDecode(msgIn, nsym)
                                                                                                                                                                                                                                                                local msg = {}
                                                                                                                                                                                                                                                                for i = 1, #msgIn do msg[i] = msgIn[i] end
                                                                                                                                                                                                                                                                local synd = rsCalcSyndromes(msg, nsym)
                                                                                                                                                                                                                                                                local maxSynd = 0
                                                                                                                                                                                                                                                                for i = 1, #synd do if synd[i] > maxSynd then maxSynd = synd[i] end end
                                                                                                                                                                                                                                                                local function trimmed(m) local o = {}; for i = 1, #m - nsym do o[i] = m[i] end; return o end
                                                                                                                                                                                                                                                                if maxSynd == 0 then return trimmed(msg), true end
                                                                                                                                                                                                                                                                local errLoc = rsFindErrorLocator(synd, nsym)
                                                                                                                                                                                                                                                                if not errLoc then return trimmed(msg), false end
                                                                                                                                                                                                                                                                local errPos = rsFindErrors(reversed(errLoc), #msg)
                                                                                                                                                                                                                                                                if not errPos then return trimmed(msg), false end
                                                                                                                                                                                                                                                                local msg2 = rsCorrectErrata(msg, synd, errPos)
                                                                                                                                                                                                                                                                local synd2 = rsCalcSyndromes(msg2, nsym)
                                                                                                                                                                                                                                                                local ok = true
                                                                                                                                                                                                                                                                for i = 1, #synd2 do if synd2[i] ~= 0 then ok = false; break end end
                                                                                                                                                                                                                                                                return trimmed(msg2), ok
                                                                                                                                                                                                                                                                end
