                                                                                                                                                                                                                                                                local function deinterleaveAndEcc(codewords, cn, version, level)
                                                                                                                                                                                                                                                                local t = RS_TABLE[version][level]
                                                                                                                                                                                                                                                                local g1c, g1t, g1d, g2c, g2t, g2d = t[1], t[2], t[3], t[4], t[5], t[6]
                                                                                                                                                                                                                                                                local nsym = g1t - g1d
                                                                                                                                                                                                                                                                local blockDataCounts = {}
                                                                                                                                                                                                                                                                for i = 1, g1c do blockDataCounts[#blockDataCounts + 1] = g1d end
                                                                                                                                                                                                                                                                for i = 1, g2c do blockDataCounts[#blockDataCounts + 1] = g2d end
                                                                                                                                                                                                                                                                local totalBlocks = g1c + g2c
                                                                                                                                                                                                                                                                local maxDc = 0
                                                                                                                                                                                                                                                                for i = 1, totalBlocks do if blockDataCounts[i] > maxDc then maxDc = blockDataCounts[i] end end
                                                                                                                                                                                                                                                                local dataParts = {}
                                                                                                                                                                                                                                                                for i = 1, totalBlocks do dataParts[i] = {} end
                                                                                                                                                                                                                                                                local ptr = 1
                                                                                                                                                                                                                                                                for i = 1, maxDc do
                                                                                                                                                                                                                                                                for bi = 1, totalBlocks do
                                                                                                                                                                                                                                                                if i <= blockDataCounts[bi] then
                                                                                                                                                                                                                                                                local dp = dataParts[bi]
                                                                                                                                                                                                                                                                dp[#dp + 1] = codewords[ptr]
                                                                                                                                                                                                                                                                ptr = ptr + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local ecParts = {}
                                                                                                                                                                                                                                                                for i = 1, totalBlocks do ecParts[i] = {} end
                                                                                                                                                                                                                                                                for i = 1, nsym do
                                                                                                                                                                                                                                                                for bi = 1, totalBlocks do
                                                                                                                                                                                                                                                                local ep = ecParts[bi]
                                                                                                                                                                                                                                                                ep[#ep + 1] = codewords[ptr]
                                                                                                                                                                                                                                                                ptr = ptr + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local allData = {}
                                                                                                                                                                                                                                                                local okAll = true
                                                                                                                                                                                                                                                                for i = 1, totalBlocks do
                                                                                                                                                                                                                                                                local full = {}
                                                                                                                                                                                                                                                                for j = 1, #dataParts[i] do full[#full + 1] = dataParts[i][j] end
                                                                                                                                                                                                                                                                for j = 1, #ecParts[i] do full[#full + 1] = ecParts[i][j] end
                                                                                                                                                                                                                                                                local corrected, ok = rsDecode(full, nsym)
                                                                                                                                                                                                                                                                if not ok then okAll = false end
                                                                                                                                                                                                                                                                for j = 1, #corrected do allData[#allData + 1] = corrected[j] end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return allData, okAll
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local ALNUM_CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:"
                                                                                                                                                                                                                                                                local function charCountBits(version, mode)
                                                                                                                                                                                                                                                                local table1_9  = { [1] = 10, [2] = 9,  [4] = 8,  [8] = 8 }
                                                                                                                                                                                                                                                                local table10_26 = { [1] = 12, [2] = 11, [4] = 16, [8] = 10 }
                                                                                                                                                                                                                                                                local table27_40 = { [1] = 14, [2] = 13, [4] = 16, [8] = 12 }
                                                                                                                                                                                                                                                                if version <= 9 then return table1_9[mode]
                                                                                                                                                                                                                                                                elseif version <= 26 then return table10_26[mode]
                                                                                                                                                                                                                                                                else return table27_40[mode] end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function bitsToInt(bits, start, n)
                                                                                                                                                                                                                                                                local v = 0
                                                                                                                                                                                                                                                                for i = 0, n - 1 do
                                                                                                                                                                                                                                                                v = bit32.bor(bit32.lshift(v, 1), bits[start + i])
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return v
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local function parseData(dataCodewords, dn, version)
                                                                                                                                                                                                                                                                local bits, bn = {}, 0
                                                                                                                                                                                                                                                                for i = 1, dn do
                                                                                                                                                                                                                                                                local b = dataCodewords[i]
                                                                                                                                                                                                                                                                for k = 7, 0, -1 do
                                                                                                                                                                                                                                                                bn = bn + 1
                                                                                                                                                                                                                                                                bits[bn] = bit32.band(bit32.rshift(b, k), 1)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local pos = 1
                                                                                                                                                                                                                                                                local segments = {}
                                                                                                                                                                                                                                                                while pos + 4 <= bn + 1 do
                                                                                                                                                                                                                                                                local mode = bitsToInt(bits, pos, 4); pos = pos + 4
                                                                                                                                                                                                                                                                if mode == 0 then break end
                                                                                                                                                                                                                                                                if mode == 1 then
                                                                                                                                                                                                                                                                local ccb = charCountBits(version, 1)
                                                                                                                                                                                                                                                                local count = bitsToInt(bits, pos, ccb); pos = pos + ccb
                                                                                                                                                                                                                                                                local s = {}
                                                                                                                                                                                                                                                                local remaining = count
                                                                                                                                                                                                                                                                while remaining >= 3 do
                                                                                                                                                                                                                                                                local v = bitsToInt(bits, pos, 10); pos = pos + 10
                                                                                                                                                                                                                                                                s[#s + 1] = ("%03d"):format(v)
                                                                                                                                                                                                                                                                remaining = remaining - 3
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if remaining == 2 then
                                                                                                                                                                                                                                                                local v = bitsToInt(bits, pos, 7); pos = pos + 7
                                                                                                                                                                                                                                                                s[#s + 1] = ("%02d"):format(v)
                                                                                                                                                                                                                                                                elseif remaining == 1 then
                                                                                                                                                                                                                                                                local v = bitsToInt(bits, pos, 4); pos = pos + 4
                                                                                                                                                                                                                                                                s[#s + 1] = ("%01d"):format(v)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                segments[#segments + 1] = table.concat(s)
                                                                                                                                                                                                                                                                elseif mode == 2 then
                                                                                                                                                                                                                                                                local ccb = charCountBits(version, 2)
                                                                                                                                                                                                                                                                local count = bitsToInt(bits, pos, ccb); pos = pos + ccb
                                                                                                                                                                                                                                                                local s = {}
                                                                                                                                                                                                                                                                local remaining = count
                                                                                                                                                                                                                                                                while remaining >= 2 do
                                                                                                                                                                                                                                                                local v = bitsToInt(bits, pos, 11); pos = pos + 11
                                                                                                                                                                                                                                                                s[#s + 1] = ALNUM_CHARS:sub(math.floor(v / 45) + 1, math.floor(v / 45) + 1)
                                                                                                                                                                                                                                                                s[#s + 1] = ALNUM_CHARS:sub((v % 45) + 1, (v % 45) + 1)
                                                                                                                                                                                                                                                                remaining = remaining - 2
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if remaining == 1 then
                                                                                                                                                                                                                                                                local v = bitsToInt(bits, pos, 6); pos = pos + 6
                                                                                                                                                                                                                                                                s[#s + 1] = ALNUM_CHARS:sub(v + 1, v + 1)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                segments[#segments + 1] = table.concat(s)
                                                                                                                                                                                                                                                                elseif mode == 4 then
                                                                                                                                                                                                                                                                local ccb = charCountBits(version, 4)
                                                                                                                                                                                                                                                                local count = bitsToInt(bits, pos, ccb); pos = pos + ccb
                                                                                                                                                                                                                                                                local s = {}
                                                                                                                                                                                                                                                                for i = 1, count do
                                                                                                                                                                                                                                                                local v = bitsToInt(bits, pos, 8); pos = pos + 8
                                                                                                                                                                                                                                                                s[#s + 1] = string.char(v)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                segments[#segments + 1] = table.concat(s)
                                                                                                                                                                                                                                                                elseif mode == 8 then
                                                                                                                                                                                                                                                                local ccb = charCountBits(version, 8)
                                                                                                                                                                                                                                                                local count = bitsToInt(bits, pos, ccb); pos = pos + ccb
                                                                                                                                                                                                                                                                pos = pos + count * 13
                                                                                                                                                                                                                                                                segments[#segments + 1] = "[kanji not supported]"
                                                                                                                                                                                                                                                                elseif mode == 7 then
                                                                                                                                                                                                                                                                pos = pos + 8
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                break
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return table.concat(segments)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                print("Locating finder patterns...")
                                                                                                                                                                                                                                                                local pts = findFinderPatterns()
                                                                                                                                                                                                                                                                local topLeft, topRight, bottomLeft = orderFinderPatterns(pts)
                                                                                                                                                                                                                                                                print("Sampling module grid...")
                                                                                                                                                                                                                                                                local matrix, dimension, mIdx = buildBitMatrix(topLeft, topRight, bottomLeft)
                                                                                                                                                                                                                                                                local version = math.floor((dimension - 17) / 4)
                                                                                                                                                                                                                                                                print(("Detected version %d (%dx%d modules)"):format(version, dimension, dimension))
                                                                                                                                                                                                                                                                local eccBits, maskId = readFormatInfo(matrix, mIdx)
                                                                                                                                                                                                                                                                local level = ECC_BITS_MAP[eccBits]
                                                                                                                                                                                                                                                                print(("ECC level: %s, mask: %d"):format(level, maskId))
                                                                                                                                                                                                                                                                local funcGrid = buildFuncGrid(dimension, version, mIdx)
                                                                                                                                                                                                                                                                local unmasked = unmaskMatrix(matrix, dimension, maskId, funcGrid, mIdx)
                                                                                                                                                                                                                                                                local codewords, cn = readCodewords(unmasked, dimension, funcGrid, mIdx)
                                                                                                                                                                                                                                                                local dataCodewords, rsOk = deinterleaveAndEcc(codewords, cn, version, level)
                                                                                                                                                                                                                                                                if not rsOk then
                                                                                                                                                                                                                                                                print("Warning: Reed-Solomon error correction reported uncorrectable errors.")
                                                                                                                                                                                                                                                                print("The result below may be inaccurate.")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local text = parseData(dataCodewords, #dataCodewords, version)
                                                                                                                                                                                                                                                                print("")
                                                                                                                                                                                                                                                                print("===== Decoded QR Text =====")
                                                                                                                                                                                                                                                                print(text)
                                                                                                                                                                                                                                                                print("============================")
                                                                                                                                                                                                                                                                if fs and args[2] ~= "--nosave" then
                                                                                                                                                                                                                                                                local out = fs.open("qrdecode_result.txt", "w")
                                                                                                                                                                                                                                                                if out then
                                                                                                                                                                                                                                                                out.write(text)
                                                                                                                                                                                                                                                                out.close()
                                                                                                                                                                                                                                                                print("(saved to qrdecode_result.txt)")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
